namespace Lastlight.Core;
public sealed partial class World
{
 public CommandResult ApplyCampaignCommand(WorldCommand c,Definitions d)
 {
  if(c.Text=="enable"){if(!Region.Enabled||!Society.Enabled)return new(false,"Enable the living region and institutions first.");EnableSolar();return new(true,"Solar observations enabled without changing the existing camp.");}if(!Solar.Enabled)return new(false,"Enable the solar campaign first.");
  if(c.Text=="mode")
  {if(!SolarModes.Contains(c.DefinitionId))return new(false,"Unknown campaign mode.");if(c.DefinitionId=="Custom"&&c.Quantity is <2 or >60)return new(false,"Custom seasons must be two to sixty days.");Solar.Mode=c.DefinitionId;Solar.SeasonDays=c.DefinitionId=="Slow Dusk"?12:c.DefinitionId=="Last Century"?6:c.DefinitionId=="Custom"?c.Quantity:12;Solar.NextBoundary=Tick+Solar.SeasonDays*TicksPerDay;Solar.AnnouncedBoundary=0;Solar.NextFlareAt=0;Solar.FlareUntil=0;Solar.FlareAnnounced=false;foreach(var f in Solar.Forecasts)f.Resolved=true;UpdateSolarStage();if(!Solar.SunRestored&&Solar.Mode!="Open Twilight"&&Solar.Stage>=2&&Solar.InstabilitySetting>0)Solar.NextFlareAt=Tick+TicksPerDay*2;Chronicle("Scenario",Solar.Mode+": "+SolarRules(),site:Region.HomeSiteId);return new(true,SolarRules());}
  if(c.Text=="director"){if(!Directors.Contains(c.DefinitionId))return new(false,"Unknown director.");Solar.Director=c.DefinitionId;Solar.NextIncidentAt=Tick+TicksPerDay*3;return new(true,"Director changed; cause, eligibility and recovery remain visible.");}
  if(c.Text=="setting")
  {if(c.Quantity is <0 or >100)return new(false,"Hazard settings must be 0–100.");switch(c.DefinitionId){case "Raids":Solar.RaidIntensity=c.Quantity;Danger.RaidsEnabled=c.Quantity>0;break;case "Scarcity":Solar.Scarcity=c.Quantity;break;case "Instability":Solar.InstabilitySetting=c.Quantity;if(c.Quantity==0){Solar.NextFlareAt=0;Solar.FlareUntil=0;}else if(!Solar.SunRestored&&Solar.Stage>=2&&Solar.Mode!="Open Twilight"&&Solar.NextFlareAt==0)Solar.NextFlareAt=Tick+TicksPerDay*2;UpdateSolarStage();break;case "Disease":Solar.Disease=c.Quantity;break;case "Stress":Solar.Stress=c.Quantity;break;default:return new(false,"Unknown independent hazard setting.");}return new(true,c.DefinitionId+" set to "+c.Quantity+"; changes are explicit scenario settings.");}
  if(c.Text=="project")
  {var project=Solar.Projects.FirstOrDefault(p=>p.Id==c.DefinitionId);if(project==null||project.Completed||Solar.Finale!=""||!Colony.People.TryGetValue(c.EntityId,out var pawn)||pawn.Drafted||!CanAct(c.EntityId)||Find(c.TargetId) is not {Forbidden:false} host||FindPath(Find(c.EntityId)!,pawn,Index(host.X,host.Y,host.Z),true,d)==null)return new(false,"Choose an incomplete project, capable undrafted worker and reachable allowed host.");if(Region.Parties.Any(p=>p.State is not ("Returned" or "Cancelled")))return new(false,"Return all expeditions before committing a finale project.");var candidate=new CampaignProject{Id=project.Id,HostId=host.Id,Phase=project.Phase};var missing=ProjectMissing(candidate);if(missing.Count>0){project.Status=string.Join("; ",missing);return new(false,project.Status);}if(Solar.Projects.Any(p=>p.Active&&p.Id!=project.Id&&p.WorkerId==c.EntityId))return new(false,"Worker already assigned to another campaign project.");if(project.WorkerId!=0)Interrupt(project.WorkerId,d);project.HostId=host.Id;project.WorkerId=c.EntityId;project.Active=true;Interrupt(c.EntityId,d);return new(true,"Project commissioned; autonomous Research/Construct work will transport materials and complete three phases.");}
  if(c.Text=="pause-project"){var project=Solar.Projects.FirstOrDefault(p=>p.Id==c.DefinitionId);if(project==null||project.Completed)return new(false,"Select unfinished project.");project.Active=false;if(project.WorkerId!=0)Interrupt(project.WorkerId,d);project.Status="Paused; work retained and carried goods returned";return new(true,project.Status);}
  if(c.Text=="patron")
  {var faction=Region.Factions.FirstOrDefault(f=>f.Id==c.TargetId);var party=Region.Parties.FirstOrDefault(p=>p.State=="AtSite"&&p.Members.Contains(c.EntityId));if(faction==null||party==null||!AtCounter(party,faction.Id,c.EntityId)||faction.Goodwill<10||Solar.Patrons.Any(p=>p.FactionId==faction.Id)||faction.Reserves.GetValueOrDefault("f-parts")<6||faction.Reserves.GetValueOrDefault("meal")<6||party.Cargo.Values.Sum()+party.Artifacts.Count+12>party.Members.Count*40||c.DefinitionId is not ("Open access" or "Supplies"))return new(false,"Patronage requires an eligible town envoy, available real aid, cargo space and a new demand choice.");faction.Reserves["f-parts"]-=6;faction.Reserves["meal"]-=6;party.Cargo["f-parts"]=party.Cargo.GetValueOrDefault("f-parts")+6;party.Cargo["meal"]=party.Cargo.GetValueOrDefault("meal")+6;var pact=new PatronCompact{Id=Solar.NextId++,FactionId=faction.Id,Demand=c.DefinitionId,DueAt=Tick+TicksPerDay*7,BaselineSessions=Society.Institutions.Where(i=>i.Kind=="Library").Sum(i=>i.Sessions)};Solar.Patrons.Add(pact);Chronicle("Patronage",faction.Name+" granted the title "+pact.Title+" and funded six meals/six parts. Obligation: "+pact.Demand+" every seven days.",faction.Id,Region.HomeSiteId,actor:c.EntityId);return new(true,"Title and actual funded aid accepted; obligations are visible and independence remains available.");}
  if(c.Text is "fulfill" or "refuse-patron")
  {var pact=Solar.Patrons.FirstOrDefault(p=>p.Id==c.TargetId&&p.Active);if(pact==null)return new(false,"No active patron demand.");var f=Region.Factions.First(f=>f.Id==pact.FactionId);if(c.Text=="refuse-patron"){pact.Active=false;pact.Result="Refused; title withdrawn";f.Grievance=Math.Min(100,f.Grievance+10);f.Trust=Math.Max(-100,f.Trust-5);Chronicle("PatronRefusal",f.Name+" withdrew its title after refusal; ten grievance and five trust were the stated consequence.",f.Id);return new(true,"Patronage ended. All independent finale paths remain available.");}
   if(pact.Demand=="Open access"){int sessions=Society.Institutions.Where(i=>i.Kind=="Library").Sum(i=>i.Sessions);if(Society.Covenant!="Open archive"||sessions<pact.BaselineSessions+4)return new(false,"Adopt Open archive and hold four new actual library sessions.");pact.BaselineSessions=sessions;}else{var party=Region.Parties.FirstOrDefault(p=>p.State=="AtSite"&&p.Members.Contains(c.EntityId));if(party==null||!AtCounter(party,f.Id,c.EntityId)||party.Cargo.GetValueOrDefault("brass")<3)return new(false,"Bring three packed brass to the patron's town counter.");party.Cargo["brass"]-=3;f.Reserves["brass"]=Math.Min(10000,f.Reserves.GetValueOrDefault("brass")+3);}pact.Payments++;pact.DueAt=Tick+TicksPerDay*7;f.Trust=Math.Min(100,f.Trust+3);pact.Result="Demand fulfilled "+pact.Payments+" times";Chronicle("PatronDemand","Fulfilled "+pact.Demand+" for "+f.Name+".",f.Id);return new(true,"Obligation fulfilled with actual practice/payment; deadline renewed.");}
  if(c.Text is "share-refuge" or "refuse-claim")
  {var claim=Solar.Claims.FirstOrDefault(q=>q.Id==c.TargetId&&q.State=="Offered");if(claim==null)return new(false,"No offered sanctuary claim.");var f=Region.Factions.First(f=>f.Id==claim.FactionId);if(c.Text=="refuse-claim"){claim.State="Disputed";claim.Result="Independence chosen; claim disputed";f.Grievance=Math.Min(100,f.Grievance+20);Chronicle("Independence","Refused "+f.Name+"'s sanctuary claim; twenty grievance recorded. Any conflict must respect signed diplomacy and a funded force budget.",f.Id,claim.SiteId);return new(true,"Independence preserved; no finale requires a patron title.");}
   if(!CanAct(c.EntityId)||!Colony.People.ContainsKey(c.EntityId)||Find(c.EntityId) is not {} actor||Entities.All(e=>e.DefinitionId!="study"||e.Z!=actor.Z||Distance(e,actor)>2)||RefugeCapacity()<Colony.People.Keys.Count(id=>Body(id) is {Dead:false})+2)return new(false,"A capable council host beside a study desk and two spare warm, dry beds are required.");int cell=Index(actor.X,actor.Y,actor.Z);for(int i=0;i<2;i++){var at=Position(NearestTerrainCell(cell,d));var result=Apply(new(CommandKind.Spawn,DefinitionId:"settler",X:at.X,Y:at.Y,Z:at.Z),d);if(!result.Accepted)throw new InvalidDataException(result.Message);Find(result.EntityId)!.Name=f.Name.Split(' ')[0]+" Refugee "+(i+1);}f.Population=Math.Max(1,f.Population-2);claim.State="Shared";claim.Result="Two actual refugees admitted";f.Claims.Remove("sanctuary:"+claim.SiteId);f.Trust=Math.Min(100,f.Trust+10);f.Goodwill=Math.Min(100,f.Goodwill+10);Chronicle("RefugeAdmission",f.Name+"'s claim was settled by admitting two people into actual spare refuge capacity.",f.Id,claim.SiteId,actor:c.EntityId);return new(true,"Two refugees admitted; beds, food and care remain real colony responsibilities.");}
  return new(false,"Unknown campaign action.");
 }
 private void AdvancePatronObligations()
 {foreach(var pact in Solar.Patrons.Where(p=>p.Active&&Tick>p.DueAt)){pact.Active=false;pact.Result="Missed obligation; title withdrawn";var f=Region.Factions.First(f=>f.Id==pact.FactionId);f.Grievance=Math.Min(100,f.Grievance+10);f.Trust=Math.Max(-100,f.Trust-5);Chronicle("PatronDemand",f.Name+" withdrew a title after its announced deadline; no aid was fabricated or reclaimed.",f.Id);}}
}
